package vn.iotstar.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*;
@Entity @Table(name="users",uniqueConstraints={@UniqueConstraint(columnNames="username"),@UniqueConstraint(columnNames="email")}) @Getter @Setter @NoArgsConstructor public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,length=50) String username; @Column(nullable=false,length=150) String email; @Column(nullable=false) String password; String fullName; String images; boolean enabled=true; LocalDateTime createdAt=LocalDateTime.now(); @ManyToOne(fetch=FetchType.EAGER,optional=false) Role role; @OneToMany(mappedBy="user",cascade=CascadeType.ALL,orphanRemoval=true) List<Product> products=new ArrayList<>(); }
